@startuml

class Bookmaker {
  + placeBet(bet : Bet) : void
}

class Bettor {
  + id : int
  + name : string
}

class Race {
  + id : int
  + winner : Runner
  + runners : Runner[]
}

class Runner {
  + id : int
  + horseName : string
  + jockey : Jockey
}

class Jockey {
  + id : int
  + name : string
}

class Bet {
  + id : int
  + bettor : Bettor
  + race : Race
  + runner : Runner
  + amount : double
  + odds : double
}

Bookmaker "1" -- "*" Bet
Bettor "1" -- "*" Bet
Race "1" -- "*" Runner
Runner "1" -- "1" Jockey

@enduml

